/// <summary>
/// desigend from AVA
/// </summary>
public void modified()
{
    FormDataObject   formDataObject = any2Object(this) as FormDataObject;
    FormDataSource   formDataSource = formDataObject.datasource();
    FormRun          formRun = formDataSource.formRun();
    ProdParmRelease  prodParmRelease = formDataSource.cursor(); ;

    next modified();


    formRun.design().controlName('AVASetupButtonProdProdOrder').enabled(prodParmRelease.AVAPrintProdProdOrder);
    formRun.design().controlName('ProdParmRelease_AVAPrintReference').enabled(prodParmRelease.AVAPrintProdProdOrder);
    if (prodParmRelease.AVAPrintProdProdOrder == NoYes::No)
    {
        prodParmRelease.AVAPrintReference =  NoYes::No; 
    } 

}
